fn fact(n) {
    if n <= 1 { 1 } else { n * fact(n - 1) }
}
fn fib(n) {
    if n < 2 { n } else { fib(n - 1) + fib(n - 2) }
}
print("fact(5) = ${fact(5)}")
print("fib(10) = ${fib(10)}")

